-- CMake supplies the module search path with the actual platform suffix.
-- Keep Lua's existing paths so other installed modules remain available.
package.cpath = assert(arg[1], "expected the demo module search path") .. ";" .. package.cpath
demo = require("demo")
local directory = debug.getinfo(1, "S").source:sub(2):match("^(.*[/\\])") or "./"
Series = dofile(directory .. "demo_protocols.lua")(demo)
Calls = dofile(directory .. "demo_calls.lua")(demo)
Generators = dofile(directory .. "demo_generators.lua")()
Callables = dofile(directory .. "demo_callables.lua")(demo)
ClassCallbacks = dofile(directory .. "demo_class_callbacks.lua")(demo)
Awaitables = dofile(directory .. "demo_awaitables.lua")(demo)
InteropA,InteropB=require("interop_a"),require("interop_b")
Interop=dofile(directory .. "demo_interop.lua")(InteropA,InteropB)

print("Rosetta demo loaded. Try: demo.demo__add(20, 22)")
print("List functions: for name in pairs(demo) do print(name) end")
print("Enums: demo.demo__apply(demo.demo__Operation.multiply, 6, 7)")
print("Templates: demo.demo__template_max_int(20, 42)")
print("Values: demo.demo__reverse_words({'one', 'two'})")
print("Classes: c = demo.demo__Counter.new(20, 'example'); c:add(22); print(c:value()); c:close()")
print("Callbacks: demo.demo__invoke_callback(function(v) return v + 2 end, 40)")
print("Inheritance: e = demo.demo__make_diamond('diamond', 42); v = e:as_value(); print(v:value()); e:close(); v:close()")
print("Operators: s = Series({20, 21}); t = s * 2; print(t[2]); for i, v in pairs(t) do print(i, v) end; s:close(); t:close()")
print("Division: s = Series({-7, 7}); q = s / 3; f = s // 3; print(q[1], f[1]); s:close(); q:close(); f:close()")
print("Time: demo.demo__time_convert(-1500, 'ms', 's', 'nearest'); p = demo.demo__time_now(true); print(p:ticks()); p:close()")
print("Products: p = demo.demo__product_identity({'tuple', 42}); print(p[1], p[2], p[3]); demo.demo__pair_identity({'key', true})")
print("Flags: demo.demo__feature_identity(demo.demo__Feature.classes | demo.demo__Feature.templates)")
print("Enum values: demo.demo__operation_vector({demo.demo__Operation.add, demo.demo__Operation.multiply})")
print("Nested: n = demo.demo__NestedOwner.new(41); i = n:item(); print(i:shifted()); i:close(); n:close()")
print("Maps: demo.demo__string_map({answer='42'}); demo.demo__optional_map({{'empty'}, {'present', '42'}})")
print("Variants: demo.demo__variant_identity({index=3, value='text'}); demo.demo__duplicate_variant({index=2, value=42}); demo.demo__variant_identity({index=1})")
print("Async: t = demo.demo__AsyncTask.new(21, 0, false); t:wait(2000); print(t:result()); t:close()")
print("Tagged values: r = demo.demo__TaggedRecord.new(); r:set_text('union string'); print(r:text()); r:close()")
print("Compile-time: demo.demo__immediate_answer(); demo.demo__template_pattern(40)")
print("Buffers: b = demo.demo__ByteBuffer.new('bytes'); v = b:slice(0, 2, false); v:write(0, '42'); print(b:read()); v:close(); b:close()")
print("Calls: Calls.choose(41); Calls.scale(21); Calls.sum({10, 20, 12})")
print("Errors: r = demo.demo__divide_result(1, 0); print(r:error_kind(), r:code(), r:message()); r:close()")
print("Transfer: a = demo.demo__make_resource('resource', 42, false); b = demo.demo__empty_resource(); a:move_to(b); print(b:text()); a:close(); b:close()")
print("Coroutines: g = demo.demo__Generator.new(40, 3, '', -1); for value in Generators.values(g) do print(value) end; g:close()")
print("Unicode: demo.demo__unicode_utf16(utf8.char(0x1f600)); demo.demo__unicode_scalar_count('hello')")
print("Exact numbers: demo.demo__unsigned128_add('18446744073709551615', '1'); demo.demo__long_double_add('40', '2')")
print("Filesystem: f = demo.demo__FileWorkspace.new(); f:write('message', 'hello'); print(f:read('message')); f:close()")
print("Containers: demo.demo__ordered_set({'z', 'a'}); demo.demo__optional_set({{}, {'text'}}); demo.demo__multi_map({{'key', 'first'}, {'key', 'second'}})")
print("Names: demo.demo_names__imported_count(); demo.demo_names__imported_operation(demo.demo__Operation.multiply)")
print("Worklists: q = demo.demo__Worklist.new(demo.demo__WorkOrder.highest); q:push('a'); q:push('z'); print(q:pop()); q:close()")
print("Concurrency: s = demo.demo__ConcurrentState.new(0, 42); s:parallel_add(4, 100, 1); print(s:load()); s:close(); demo.demo__thread_local_probe(7)")
print("Members: o = demo.demo__MemberObject.new(20, 21, 'example', true); m = demo.demo__MemberSelector.new(demo.demo__MemberChoice.measure); print(m:invoke_read(o, 0)); m:close(); o:close()")
print("Native ABI: n = demo.demo__NativeBoundary.new(demo.demo__BoundaryOperation.add, 20, 'payload'); print(n:with_callback(function(v) return v + 1 end, 21)); n:close(); demo.demo__native_abi_info()")
print("Native build: demo.demo__native_modules_available(); demo.demo__native_module_shift(40); demo.demo__native_header_unit_answer(); demo.demo__native_pch_shift(40)")
print("Native forms: s = demo.demo__NativeStationary.new('stable', false); t = s:share(); print(s:same(t), s:text()); s:close(); t:close(); demo.demo__native_matrix_shift({{1,2,3},{4,5,6}},40)")
print("Returned callables: f = Callables.capture('answer:', 40); print(f(2)); g = f:copy(); f:close(); print(g(0)); g:close()")
print("Class callbacks: r=demo.demo__CallbackRecord.new('record',40); s=ClassCallbacks.transform(r,function(v) v:set_number(v:number()+2); return v end); print(s:number()); s:close(); r:close()")
print("Awaitables: e=demo.demo__AwaitExecutor.new(); t=e:submit(40,2,'answer:',false,nil); print(Awaitables.result(e,t,3)); t:close(); e:close()")
print("Module exchange: a=Interop.new_a('shared',40); b=Interop.to_b(a); b:shift(2); print(a:value()); a:close(); b:close()")
